probes.shared:
struct Triple { public long a; public long b; public long c; }
var s = new Triple{a = 1, b = 2, c = 3};
var v = new List<Triple>{s, s};
var tmp = v[0];
tmp.a = 99;
v[0] = tmp;
string r = (v[1].a == 99) ? "shared" : "copied";

probes.diamond:
