identity.pre:
using System.Collections.Generic;
class Box { public List<long> items; public Box(List<long> i) { items = i; } }
class Node { public string name; public Node? self; }

probes.shared:
var baseList = new List<long>{1, 2, 3};
var s = new Box(baseList);
var v = new List<Box>{s, s};
v[0].items.Add(99);
string r = (v[1].items[v[1].items.Count - 1] == 99 && ReferenceEquals(v[0], v[1])) ? "shared" : "copied";

probes.diamond:
var t = new Box(new List<long>{7});
var v = new List<Box>{t, t};
string r = ReferenceEquals(v[0], v[1]) ? "same" : "distinct";

probes.cycle:
var n = new Node{name = "loop"};
n.self = n;
string r = ReferenceEquals(n.self, n) ? "cycle" : "no-cycle";

